import ast, inspect, warnings
import numpy as np
from control.nlsys import _process_vector_argument

TRACK = {"arg","i","name","nelem","size","v","val","val_list"}

src, start = inspect.getsourcelines(_process_vector_argument)
source = ''.join(src)
mod = ast.parse(source)
func = mod.body[0]

line_ops = {}

def add_op(lineno, op, var):
    if var in TRACK:
        line_ops.setdefault(start + lineno - 1, []).append((op, var))

class V(ast.NodeVisitor):
    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Load):
            add_op(node.lineno, 'use', node.id)
        elif isinstance(node.ctx, ast.Store):
            add_op(node.lineno, 'def', node.id)
        self.generic_visit(node)

    def visit_arg(self, node):
        pass

v = V()
v.visit(func)

# parameter defs on function def line
for a in func.args.args:
    add_op(func.lineno, 'def', a.arg)


def run_case(arg, name, size):
    pairs = set()
    current_def = {}

    def tracer(frame, event, arginfo):
        if frame.f_code is _process_vector_argument.__code__:
            if event == 'call':
                # initialize param defs
                for p in ['arg','name','size']:
                    current_def[p] = start + func.lineno - 1
                return tracer
            if event == 'line':
                ln = frame.f_lineno
                ops = line_ops.get(ln, [])
                # uses before defs on same line
                for op, var in ops:
                    if op == 'use' and var in current_def:
                        pairs.add((var, current_def[var], ln))
                for op, var in ops:
                    if op == 'def':
                        current_def[var] = ln
        return tracer

    import sys
    old = sys.gettrace()
    sys.settrace(tracer)
    try:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            _process_vector_argument(arg, name, size)
    finally:
        sys.settrace(old)
    return pairs

cases = [
    (([1.0], [2.0], [0.0]), 'case01', 6),
    (([1.0, 2.0], [0.0]), 'case02', 5),
    ((np.array([3.0]), [4.0], [0.0]), 'case03', 5),
    (([5.0, 6.0], np.array([0.0])), 'case04', 6),
    (([7.0], (8.0,), [0.0]), 'case05', 7),
    ((np.array([[1.0, 2.0]]), [0.0]), 'case06', 6),
    (([9.0], np.array([[10.0]]), [0.0]), 'case07', 6),
    (([11.0, 12.0], [13.0], [0.0]), 'case08', 7),
    ((np.array([14.0]), np.array([0.0])), 'case09', 5),
    (([15.0], [16.0, 17.0], [0.0]), 'case10', 8),
]

all_sets = [run_case(*c) for c in cases]
inter = set.intersection(*all_sets)

for idx,s in enumerate(all_sets,1):
    print('case',idx,'pairs',len(s))
print('intersection',len(inter))
for p in sorted(inter, key=lambda x:(x[0],x[1],x[2])):
    print(p)
